import 'package:drift/drift.dart';

/// One recorded drive. `phase` is a [TripPhase] wire value.
///
/// Raw samples live in [Samples] with a 90-day TTL; everything else here is
/// kept for the account's life (or until the user deletes the trip).
@TableIndex(name: 'trips_started_at', columns: {#startedAt})
class Trips extends Table {
  /// UUID generated by the native plugin (or the simulator).
  TextColumn get id => text()();

  /// Epoch ms of the first confirmed fix (or the tentative trigger until then).
  IntColumn get startedAt => integer()();
  IntColumn get endedAt => integer().nullable()();

  /// recording | pendingPassenger | scored | unscored | discarded
  TextColumn get phase => text()();

  /// stationary | exit | manual
  TextColumn get endReason => text().nullable()();

  /// activity | bluetooth | geofence | significantChange | manual | simulated
  TextColumn get triggerKind => text().nullable()();
  RealColumn get distanceM => real().withDefault(const Constant(0))();
  RealColumn get movingS => real().withDefault(const Constant(0))();

  /// Null until the trip has been finalised once.
  BoolColumn get isPassenger => boolean().nullable()();

  /// Pre-answer for the passenger interstitial, from native hints.
  BoolColumn get passengerHint =>
      boolean().withDefault(const Constant(false))();

  /// True once the user has confirmed or changed the passenger answer.
  BoolColumn get passengerAnswered =>
      boolean().withDefault(const Constant(false))();

  /// Bluetooth / CarPlay / Android Auto name seen during the trip.
  TextColumn get vehicleLabel => text().nullable()();
  TextColumn get packRegion => text().nullable()();
  TextColumn get packVersion => text().nullable()();
  RealColumn get limitCoverage => real().nullable()();
  RealColumn get nightFraction => real().nullable()();

  /// clear | rain | snow
  TextColumn get weather => text().nullable()();
  IntColumn get createdAt => integer()();

  /// Soft delete: hidden everywhere, purged with the samples.
  IntColumn get deletedAt => integer().nullable()();

  @override
  Set<Column> get primaryKey => {id};
}

/// 1 Hz GPS fixes. Never leave the phone. Purged after 90 days.
class Samples extends Table {
  TextColumn get tripId => text()();
  IntColumn get t => integer()();
  RealColumn get lat => real()();
  RealColumn get lon => real()();
  RealColumn get speed => real().nullable()();
  RealColumn get accuracy => real()();
  RealColumn get heading => real().nullable()();
  RealColumn get altitude => real().nullable()();

  @override
  Set<Column> get primaryKey => {tripId, t};
}

/// Per-second horizontal acceleration peaks above 2.5 m/s² (docs/08 §4).
class MotionPeaks extends Table {
  TextColumn get tripId => text()();
  IntColumn get t => integer()();
  RealColumn get peak => real()();

  @override
  Set<Column> get primaryKey => {tripId, t};
}

/// Phone events already mapped to the scoring engine's kinds
/// (`unlock`, `interaction`, `call_handheld`).
@DataClassName('PhoneEventRow')
class PhoneEvents extends Table {
  TextColumn get tripId => text()();
  IntColumn get t => integer()();
  TextColumn get kind => text()();

  @override
  Set<Column> get primaryKey => {tripId, t, kind};
}

/// Map-matched road segments, the scoring engine's `RoadSegment` input.
class Segments extends Table {
  TextColumn get tripId => text()();
  IntColumn get fromIdx => integer()();
  IntColumn get toIdx => integer()();
  RealColumn get speedLimitMps => real().nullable()();
  RealColumn get confidence => real()();
  TextColumn get roadClass => text()();
  TextColumn get name => text().nullable()();
  TextColumn get wayId => text().nullable()();

  @override
  Set<Column> get primaryKey => {tripId, fromIdx};
}

/// The engine's output for one trip. `scoreJson` is `TripScore.toJson()`.
@DataClassName('TripScoreRow')
class TripScores extends Table {
  TextColumn get tripId => text()();
  TextColumn get scoreJson => text()();
  IntColumn get score => integer().nullable()();
  IntColumn get xp => integer()();
  BoolColumn get reckless => boolean()();
  BoolColumn get scored => boolean()();
  TextColumn get roastText => text().nullable()();
  IntColumn get scoredAt => integer()();

  @override
  Set<Column> get primaryKey => {tripId};
}

/// Installed speed-limit packs (docs/07-pack-format.md).
class Packs extends Table {
  TextColumn get region => text()();
  TextColumn get name => text()();
  TextColumn get osmTimestamp => text()();
  TextColumn get path => text()();
  TextColumn get sha256 => text()();
  IntColumn get bytes => integer()();
  IntColumn get wayCount => integer()();
  RealColumn get bboxMinLat => real()();
  RealColumn get bboxMinLon => real()();
  RealColumn get bboxMaxLat => real()();
  RealColumn get bboxMaxLon => real()();
  IntColumn get installedAt => integer()();

  @override
  Set<Column> get primaryKey => {region};
}

/// "Limit is wrong here" flags waiting to be synced (Stage 2).
class LimitFlags extends Table {
  IntColumn get id => integer().autoIncrement()();
  TextColumn get wayId => text()();
  TextColumn get region => text().nullable()();
  TextColumn get tripId => text().nullable()();
  RealColumn get suggestedMps => real()();
  IntColumn get createdAt => integer()();
  BoolColumn get synced => boolean().withDefault(const Constant(false))();
}

/// Key/value app settings (`units`, …).
class Settings extends Table {
  TextColumn get key => text()();
  TextColumn get value => text()();

  @override
  Set<Column> get primaryKey => {key};
}

/// Fix batches already ingested, so a replayed spool is idempotent.
class FixBatches extends Table {
  TextColumn get tripId => text()();
  IntColumn get batchT => integer()();

  @override
  Set<Column> get primaryKey => {tripId, batchT};
}

// --------------------------------------------------------------------------
// Stage 2: cloud sync (docs/03 §7). Added in schema version 2.
// --------------------------------------------------------------------------

/// Pending cloud writes. Each row is one idempotent operation; [id] is the
/// client-generated key the handler uses to make retries safe.
class Outbox extends Table {
  TextColumn get id => text()();
  TextColumn get kind => text()();
  TextColumn get payload => text()();
  IntColumn get createdAt => integer()();
  IntColumn get attempts => integer().withDefault(const Constant(0))();
  IntColumn get nextAttemptAt => integer().withDefault(const Constant(0))();
  TextColumn get lastError => text().nullable()();

  @override
  Set<Column> get primaryKey => {id};
}

/// JSON snapshots of cloud reads (feed pages, standings, friends) so every
/// social screen renders offline with stale data.
class RemoteCache extends Table {
  TextColumn get key => text()();
  TextColumn get json => text()();
  IntColumn get updatedAt => integer()();

  @override
  Set<Column> get primaryKey => {key};
}

/// Which trips have been uploaded, and the hash of what was sent, so a
/// re-scored trip (passenger re-mark) is uploaded again.
class UploadedTrips extends Table {
  TextColumn get tripId => text()();
  IntColumn get uploadedAt => integer()();
  TextColumn get summaryHash => text()();

  @override
  Set<Column> get primaryKey => {tripId};
}

/// Badges awarded on this phone; synced to `user_badges` through the outbox.
class BadgeAwards extends Table {
  TextColumn get badgeId => text()();
  IntColumn get awardedAt => integer()();
  BoolColumn get synced => boolean().withDefault(const Constant(false))();

  @override
  Set<Column> get primaryKey => {badgeId};
}
